    "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n//\n// UTILISATEURS\n//\n\nmodel User {\n  id           String     @id @default(uuid())\n  token        String     @unique\n  profileToken String?    @unique\n  avatarUrl    String?\n  name         String?    @unique\n  status       UserStatus @default(OFFLINE)\n  isPublic     Boolean    @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Amis\n  friendshipsSent     Friendship[] @relation(\"FriendshipRequester\")\n  friendshipsReceived Friendship[] @relation(\"FriendshipAddressee\")\n\n  invitesSent     GameInvite[] @relation(\"InviteSender\")\n  invitesReceived GameInvite[] @relation(\"InviteReceiver\")\n\n  // Scores et succès\n  leaderboardScores LeaderboardScore[]\n  achievements      UserAchievement[]\n\n  // Parties\n  games GameUser[]\n\n  @@index([status])\n}\n\nmodel Success {\n  id String @id @default(uuid())\n\n  gameId String\n  game   Game   @relation(fields: [gameId], references: [id], onDelete: Cascade)\n\n  title       String\n  description String?\n  rarity      SuccessRarity @default(COMMON)\n\n  earnedBy GameUserSuccess[]\n\n  createdAt DateTime @default(now())\n\n  @@index([gameId])\n}\n\nmodel GameUser {\n  id String @id @default(uuid())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  gameId String\n  game   Game   @relation(fields: [gameId], references: [id], onDelete: Cascade)\n\n  status PlayerStatus @default(JOINED)\n\n  stats Json?\n\n  successes GameUserSuccess[]\n\n  joinedAt    DateTime @default(now())\n  playedHours String\n\n  @@unique([userId, gameId])\n  @@index([gameId])\n  @@index([userId])\n  @@index([gameId, status])\n}\n\nmodel GameUserSuccess {\n  id String @id @default(uuid())\n\n  gameUserId String\n  gameUser   GameUser @relation(fields: [gameUserId], references: [id], onDelete: Cascade)\n\n  successId String\n  success   Success @relation(fields: [successId], references: [id], onDelete: Cascade)\n\n  earnedAt DateTime @default(now())\n\n  @@unique([gameUserId, successId])\n  @@index([successId])\n}\n\nenum UserStatus {\n  ONLINE\n  IN_GAME\n  AWAY\n  OFFLINE\n}\n\n//\n// RARETÉ DES SUCCÈS\n//\n\nenum SuccessRarity {\n  COMMON\n  UNCOMMON\n  RARE\n  EPIC\n  LEGENDARY\n}\n\n//\n// AMIS\n//\n\nmodel Friendship {\n  id String @id @default(uuid())\n\n  requesterId String\n  requester   User   @relation(\"FriendshipRequester\", fields: [requesterId], references: [id], onDelete: Cascade)\n\n  addresseeId String\n  addressee   User   @relation(\"FriendshipAddressee\", fields: [addresseeId], references: [id], onDelete: Cascade)\n\n  status    FriendshipStatus @default(PENDING)\n  createdAt DateTime         @default(now())\n  updatedAt DateTime         @updatedAt\n\n  @@unique([requesterId, addresseeId])\n  @@index([requesterId, status])\n  @@index([addresseeId, status])\n}\n\nenum FriendshipStatus {\n  PENDING\n  ACCEPTED\n  DECLINED\n  BLOCKED\n}\n\n//\n// JEUX\n//\n\nmodel Game {\n  id          String  @id @default(uuid())\n  slug        String  @unique\n  name        String  @unique\n  description String? @db.Text\n  tag         String?\n  coverUrl    String?\n  launchUrl   String?\n\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Parties\n  invites GameInvite[]\n\n  // Leaderboard\n  leaderboards Leaderboard[]\n\n  // Succès\n  achievements Achievement[]\n  successes    Success[]\n  gameUsers    GameUser[]\n\n  @@index([isActive])\n}\n\n//\n// PARTIES\n//\n\nenum PlayerStatus {\n  INVITED\n  JOINED\n  PLAYING\n  FINISHED\n  LEFT\n  DECLINED\n}\n\n//\n// INVITATIONS À UNE PARTIE\n//\n\nmodel GameInvite {\n  id String @id @default(uuid())\n\n  senderId String\n  sender   User   @relation(\"InviteSender\", fields: [senderId], references: [id], onDelete: Cascade)\n\n  receiverId String\n  receiver   User   @relation(\"InviteReceiver\", fields: [receiverId], references: [id], onDelete: Cascade)\n\n  gameId String\n  game   Game   @relation(fields: [gameId], references: [id], onDelete: Cascade)\n\n  status      InviteStatus @default(PENDING)\n  createdAt   DateTime     @default(now())\n  respondedAt DateTime?\n\n  @@index([receiverId, status])\n}\n\nenum InviteStatus {\n  PENDING\n  ACCEPTED\n  DECLINED\n  EXPIRED\n}\n\n//\n// LEADERBOARD\n//\n\nmodel Leaderboard {\n  id String @id @default(uuid())\n\n  gameId String\n  game   Game   @relation(fields: [gameId], references: [id], onDelete: Cascade)\n\n  name      String\n  period    LeaderboardPeriod @default(ALL_TIME)\n  sortOrder SortOrder         @default(DESC)\n\n  scores LeaderboardScore[]\n\n  @@unique([gameId, period])\n  @@index([gameId])\n}\n\nenum LeaderboardPeriod {\n  DAILY\n  WEEKLY\n  MONTHLY\n  ALL_TIME\n}\n\nenum SortOrder {\n  ASC\n  DESC\n}\n\nmodel LeaderboardScore {\n  id String @id @default(uuid())\n\n  leaderboardId String\n  leaderboard   Leaderboard @relation(fields: [leaderboardId], references: [id], onDelete: Cascade)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  score      Float\n  recordedAt DateTime @default(now())\n\n  @@index([leaderboardId, score])\n  @@index([userId])\n}\n\n//\n// SUCCÈS\n//\n\nmodel Achievement {\n  id String @id @default(uuid())\n\n  gameId String\n  game   Game   @relation(fields: [gameId], references: [id], onDelete: Cascade)\n\n  name        String\n  description String?\n  iconUrl     String?\n  points      Int     @default(10)\n  isSecret    Boolean @default(false)\n\n  users UserAchievement[]\n\n  @@unique([gameId, name])\n  @@index([gameId])\n}\n\nmodel UserAchievement {\n  id String @id @default(uuid())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  achievementId String\n  achievement   Achievement @relation(fields: [achievementId], references: [id], onDelete: Cascade)\n\n  unlockedAt DateTime @default(now())\n\n  @@unique([userId, achievementId])\n  @@index([achievementId])\n}\n",
